// Validates one day's Claude usage records posted by the daily Cowork collector
// (Claude in Chrome, claude.ai Analytics) and decides where they go.
// The key proves the post came from our task. Records are rebuilt with only the
// dashboard's ClaudeDailyRecord fields, so nothing extra is ever forwarded.
const KEY = 'cui_44c4f74de0a30480b007fc89d968e2fb';
const MAX_RECORDS = 3000;
const INT_FIELDS = ['sessions', 'linesAdded', 'linesRemoved', 'commits', 'pullRequests', 'toolAccepted', 'toolRejected'];
const MODEL_FIELDS = ['inputTokens', 'outputTokens', 'cacheReadTokens', 'cacheCreationTokens', 'costCents'];
const isCount = (v) => Number.isInteger(v) && v >= 0 && v <= 1e13;

const body = ($input.first().json || {}).body || {};
const summary = { ok: false, route: 'reject', target: null, dry_run: true, received: 0, accepted: 0, rejected: 0, dates: [], reasons: [] };
const reason = (r) => { if (summary.reasons.length < 15) summary.reasons.push(r); };

let p = null;
try { p = typeof body.data === 'string' ? JSON.parse(body.data) : (body.records ? body : null); }
catch (e) { reason('payload is not valid JSON'); }
if (!p && !summary.reasons.length) reason('no payload in field "data"');
if (p && p.key !== KEY) { reason('invalid key'); p = null; }

const records = [];
if (p) {
  summary.target = p.target === 'prod' ? 'prod' : (p.target === 'stage' ? 'stage' : null);
  summary.dry_run = p.dry_run !== false;
  if (!summary.target) reason('target must be "stage" or "prod"');
  const list = Array.isArray(p.records) ? p.records : [];
  if (!Array.isArray(p.records)) reason('records must be an array');
  if (list.length > MAX_RECORDS) reason('too many records (' + list.length + '), max ' + MAX_RECORDS);
  const todayUtc = new Date().toISOString().slice(0, 10);
  const byKey = new Map();
  for (const r of list.slice(0, MAX_RECORDS)) {
    summary.received++;
    const bad = (why) => { summary.rejected++; reason(why); };
    if (!r || typeof r !== 'object') { bad('record is not an object'); continue; }
    const date = String(r.date || '');
    const email = String(r.email || '').trim().toLowerCase();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || isNaN(Date.parse(date + 'T00:00:00Z')) || date > todayUtc || date < '2025-01-01') { bad('bad date ' + date); continue; }
    if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email) || email.length > 254) { bad('bad email on ' + date); continue; }
    if (!INT_FIELDS.every((f) => isCount(r[f]))) { bad('bad counts for ' + email + ' on ' + date); continue; }
    const models = Array.isArray(r.byModel) ? r.byModel : null;
    if (!models || models.length > 40) { bad('bad byModel for ' + email + ' on ' + date); continue; }
    const cleanModels = [];
    let modelsOk = true;
    for (const m of models) {
      const name = m && typeof m.model === 'string' ? m.model.trim() : '';
      if (!name || name.length > 120 || !MODEL_FIELDS.every((f) => isCount(m[f]))) { modelsOk = false; break; }
      cleanModels.push({ model: name, inputTokens: m.inputTokens, outputTokens: m.outputTokens, cacheReadTokens: m.cacheReadTokens, cacheCreationTokens: m.cacheCreationTokens, costCents: m.costCents });
    }
    if (!modelsOk) { bad('bad model row for ' + email + ' on ' + date); continue; }
    const rec = { date, email };
    for (const f of INT_FIELDS) rec[f] = r[f];
    rec.byModel = cleanModels;
    byKey.set(date + '|' + email, rec);   // later duplicate of the same date+email wins
  }
  for (const rec of byKey.values()) records.push(rec);
  summary.accepted = records.length;
  summary.dates = [...new Set(records.map((r) => r.date))].sort();
  summary.users = new Set(records.map((r) => r.email)).size;

  if (summary.target && list.length <= MAX_RECORDS) {
    summary.ok = true;
    if (summary.received === 0) summary.route = 'empty';
    else if (summary.accepted === 0) { summary.ok = false; summary.route = 'reject'; }
    else summary.route = summary.dry_run ? 'dry_run' : summary.target;
  }
}
// The dashboard rejects request bodies over ~100 KB ("request entity too large"),
// so records are split into batches of at most MAX_BYTES of JSON. The dashboard
// upserts by (date, email), so splitting changes nothing about what's stored.
const MAX_BYTES = 80000;
const chunks = [];
let cur = [], size = 15;
for (const rec of records) {
  const s = JSON.stringify(rec).length + 1;
  if (cur.length && size + s > MAX_BYTES) { chunks.push(cur); cur = []; size = 15; }
  cur.push(rec); size += s;
}
if (cur.length || !chunks.length) chunks.push(cur);
summary.batches = chunks.length;
return chunks.map((c, i) => ({ json: { summary, batch: i + 1, payload: { records: c } } }));

// One item per batch arrives from Dashboard result. Combine them into one answer
// for the collector: totals across batches and the union of unmatched emails.
const items = $input.all().map((i) => i.json);
const okCount = items.filter((x) => x.dashboard_ok === true).length;
const sum = (k) => items.reduce((a, x) => a + (Number(x.dashboard_json && x.dashboard_json[k]) || 0), 0);
const emails = [...new Set(items.flatMap((x) => (x.dashboard_json && Array.isArray(x.dashboard_json.unmatchedEmails)) ? x.dashboard_json.unmatchedEmails : []))].sort();
const bad = items.find((x) => x.dashboard_ok !== true);
return [{ json: {
  batches: items.length,
  batches_ok: okCount,
  dashboard_ok: items.length > 0 && okCount === items.length,
  dashboard_status: bad ? (bad.dashboard_status ?? null) : (items.length ? items[0].dashboard_status : null),
  dailyWritten: sum('dailyWritten'),
  unmatchedWritten: sum('unmatchedWritten'),
  unmatchedEmails: emails,
  dashboard_body: bad ? (bad.dashboard_body ?? null) : null
} }];

